const rows = $json.data ?? [];

if (!Array.isArray(rows)) {
  throw new Error(
    'Respuesta inesperada de Directus'
  );
}

const query =
  $('Code · Prepare Search').item.json.query;

const results = rows.map(contact => {
  const phones =
    Array.isArray(contact.phones)
      ? contact.phones
      : [];

  const primaryPhone =
    phones.find(
      phone => phone?.is_primary === true
    ) ??
    phones[0] ??
    null;

  return {
    contact: {
      id: contact.id,
      first_name:
        contact.first_name ?? null,

      last_name:
        contact.last_name ?? null,

      company:
        contact.company ?? null,

      email:
        contact.email ?? null,

      status:
        contact.status ?? null,

      notes:
        contact.notes ?? null
    },

    primary_phone:
      primaryPhone,

    phones
  };
});

let status;

if (results.length === 0) {
  status = 'not_found';
} else if (results.length === 1) {
  status = 'single';
} else {
  status = 'multiple';
}

return [
  {
    json: {
      status,
      query,
      count: results.length,
      results
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const query = clean(input.query);

if (!query) {
  throw new Error('query es obligatorio');
}

let limit = Number(input.limit ?? 20);

if (
  !Number.isInteger(limit) ||
  limit < 1
) {
  throw new Error(
    `limit inválido: ${input.limit}`
  );
}

limit = Math.min(limit, 50);

/*
 * Versión compacta del término para facilitar
 * búsquedas telefónicas.
 *
 * No sustituye al normalizador oficial del
 * Resolve Contact by Phone.
 */

const phoneLike =
  query.replace(/[^\d+]/g, '');

const filters = [
  {
    first_name: {
      _icontains: query
    }
  },
  {
    last_name: {
      _icontains: query
    }
  },
  {
    company: {
      _icontains: query
    }
  },
  {
    email: {
      _icontains: query
    }
  },
  {
    phones: {
      phone_number: {
        _icontains: query
      }
    }
  }
];

if (phoneLike.length >= 6) {
  filters.push({
    phones: {
      phone_normalized: {
        _icontains: phoneLike
      }
    }
  });
}

return [
  {
    json: {
      query,

      phone_like:
        phoneLike.length >= 6
          ? phoneLike
          : null,

      limit,

      filter: {
        _or: filters
      }
    }
  }
];
